// simple djb2-style hash (no require)
function simpleHash(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h) ^ str.charCodeAt(i);
  return (h >>> 0).toString(16).padStart(8, '0') + str.length.toString(16).padStart(8, '0');
}
const results = [];
const targetDate = $('Set Target Date').first().json.targetDate;
const inputs = $input.all();

function toBeijingDate(dateStr) {
  if (!dateStr) return null;
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return null;
    const beijing = new Date(d.getTime() + 8 * 60 * 60 * 1000);
    return beijing.toISOString().split('T')[0];
  } catch (e) {
    return null;
  }
}

const todayBeijing = toBeijingDate(new Date().toISOString());
const effectiveTarget = toBeijingDate(targetDate) || todayBeijing;


function extractTag(xml, tag) {
  const cdataRegex = new RegExp('<' + tag + '[^>]*>\\s*<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>\\s*</' + tag + '>', 'i');
  const cdataMatch = xml.match(cdataRegex);
  if (cdataMatch) return cdataMatch[1].trim();
  const plainRegex = new RegExp('<' + tag + '[^>]*>\\s*([\\s\\S]*?)\\s*</' + tag + '>', 'i');
  const plainMatch = xml.match(plainRegex);
  if (plainMatch) return plainMatch[1].trim();
  return '';
}

function decodeEntities(str) {
  return str.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&apos;/g, "'");
}

function extractFirstImage(html) {
  const decoded = decodeEntities(html);
  const imgMatch = decoded.match(/<img[^>]+src=["']([^"']+)["']/i);
  return imgMatch ? imgMatch[1] : '';
}

function getSourceName(xmlString) {
  const title = extractTag(xmlString, 'title');
  if (title.includes('量子位') || xmlString.includes('qbitai')) return 'Qbitai';
  if (title.includes('机器之心') || xmlString.includes('almosthuman') || xmlString.includes('jiqizhixin')) return 'Synced';
  if (title.includes('Synced') || xmlString.includes('syncedreview')) return 'SyncedReview';
  if (title.includes('36') || xmlString.includes('36kr')) return '36Kr';
  if (title.includes('IT之家') || title.includes('IT 之家') || xmlString.includes('ithome')) return 'ITHome';
  if (title.includes('新智元') || xmlString.includes('AI_era')) return 'XinZhiYuan';
  if (title.includes('虎嗅') || xmlString.includes('huxiu')) return 'Huxiu';
  return title || 'Unknown';
}

for (const input of inputs) {
  const data = input.json;
  if (!data) continue;
  if (data.error || data.errorMessage) continue;
  const xmlString = data.data || '';
  if (!xmlString || typeof xmlString !== 'string' || !xmlString.includes('<item>')) continue;
  const sourceName = getSourceName(xmlString);
  const itemRegex = /<item>[\s\S]*?<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xmlString)) !== null) {
    const itemXml = match[0];
    const title = extractTag(itemXml, 'title');
    const link = extractTag(itemXml, 'link');
    const pubDate = extractTag(itemXml, 'pubDate');
    let rawContent = extractTag(itemXml, 'content:encoded');
    if (!rawContent) { rawContent = extractTag(itemXml, 'description'); }
    const fullContent = decodeEntities(rawContent);
    let thumbnail = extractTag(itemXml, 'thumbnail');
    if (!thumbnail) { thumbnail = extractFirstImage(rawContent); }
    const newsDate = toBeijingDate(pubDate);
    if (!newsDate) continue;
    if (newsDate === effectiveTarget) {
      const hashInput = link + '_' + newsDate;
      const content_hash = simpleHash(hashInput);
      results.push({ json: { title_cn: title, content_cn: fullContent, source_url: link, source_name: sourceName, news_date: newsDate, content_hash: content_hash, thumbnail_url: thumbnail, status: 'pending' } });
    }
  }
}
const seen = new Set();
const unique = results.filter(item => { if (seen.has(item.json.content_hash)) return false; seen.add(item.json.content_hash); return true; });

// Title similarity based cross-source dedup
function normalizeTitle(t) {
  return t.replace(/[\s\u3000!！?？,，.。:：;；""''「」【】《》\-—|｜]/g, '').toLowerCase();
}
function titleSimilarity(a, b) {
  const na = normalizeTitle(a), nb = normalizeTitle(b);
  if (na === nb) return 1.0;
  const longer = na.length >= nb.length ? na : nb;
  const shorter = na.length < nb.length ? na : nb;
  if (longer.length === 0) return 1.0;
  if (longer.includes(shorter) || shorter.includes(longer)) return 0.9;
  let matches = 0;
  for (let i = 0; i < shorter.length; i++) {
    if (longer.includes(shorter[i])) matches++;
  }
  return matches / longer.length;
}

const titleFiltered = [];
for (const item of unique) {
