    const sim = titleSimilarity(existing.json.title_cn, item.json.title_cn);
    return sim >= 0.8;
  });
  if (!dominated) titleFiltered.push(item);
}

if (titleFiltered.length === 0) return [{ json: { noResults: true, message: 'No news found for target date: ' + effectiveTarget } }];
console.log(`Merge and Filter: ${results.length} total RSS items, ${unique.length} unique by hash, ${titleFiltered.length} after title dedup for ${effectiveTarget}`);
return titleFiltered;

