const respItem = $input.first();
const resp = respItem.json;
const mergedData = $('Merge Embedding Data').first().json;
const items = mergedData.items;
const simResults = Array.isArray(resp.results) ? resp.results : [];
const similarSet = new Set();
for (const r of simResults) {
  if (r && r.is_similar) similarSet.add(r.item_index);
}
const results = [];
let similarSkipped = 0;
for (let i = 0; i < items.length; i++) {
  if (similarSet.has(i)) {
    similarSkipped++;
    continue;
  }
  results.push({ json: items[i] });
}
console.log('Similarity: ' + items.length + ' checked, ' + similarSkipped + ' similar removed, ' + results.length + ' passed');
if (results.length === 0) return [{ json: { noNewItems: true, message: 'All filtered by similarity' } }];
return results;

const aiItems = $input.all();
const translationItems = $('Parse Polish').all();
const results = [];

function extractJson(text) {
  if (!text || typeof text !== 'string') return null;
  let cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { return JSON.parse(jsonMatch[0]); } catch (e) {}
  }
  const obj = {};
  const fieldPatterns = [
    ['ai_insights_en', /"ai_insights_en"\s*:\s*"((?:[^"\\]|\\.)*)"/],
    ['ai_insights_kr', /"ai_insights_kr"\s*:\s*"((?:[^"\\]|\\.)*)"/],
    ['ai_insights_cn', /"ai_insights_cn"\s*:\s*"((?:[^"\\]|\\.)*)"/],
  ];
  let found = false;
  for (const [key, pattern] of fieldPatterns) {
    const m = cleaned.match(pattern);
    if (m) { obj[key] = m[1]; found = true; }
  }
  const ktMatch = cleaned.match(/"key_terms"\s*:\s*(\[[\s\S]*?\])/);
  if (ktMatch) {
    try { obj.key_terms = JSON.parse(ktMatch[1]); found = true; } catch (e) {}
  }
  return found ? obj : null;
}

for (let i = 0; i < aiItems.length; i++) {
  const aiData = aiItems[i].json;
  const transData = translationItems[i]?.json || {};
  let aiResponse = null;
